// Disposable, device-local previews and parsed references. Manuscripts and keys stay separate.
const memory=new Map(),DB='bookwiz-preview-cache-v1',LIMIT=24*1024*1024;let opening;
function database(){if(!globalThis.indexedDB)return Promise.resolve(null);if(!opening)opening=new Promise(resolve=>{let request;try{request=indexedDB.open(DB,1);}catch{resolve(null);return;}request.onupgradeneeded=()=>request.result.createObjectStore('entries',{keyPath:'key'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null);request.onblocked=()=>resolve(null);});return opening;}
async function transact(mode,action){const db=await database();if(!db)return null;return new Promise(resolve=>{let tx,request;try{tx=db.transaction('entries',mode);request=action(tx.objectStore('entries'));}catch{resolve(null);return;}request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null);tx.onabort=()=>resolve(null);});}
export async function digest(text){const bytes=typeof text==='string'?new TextEncoder().encode(text):text;const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');}
export async function cacheGet(key){const item=memory.get(key)||await transact('readonly',s=>s.get(key));if(!item)return null;if(item.expires<Date.now()){memory.delete(key);await transact('readwrite',s=>s.delete(key));return null;}memory.set(key,item);return item.value;}
export async function cachePut(key,value,{kind='preview',days=7}={}){const bytes=new TextEncoder().encode(JSON.stringify(value)).length;if(bytes>2000000)return false;const item={key,value,kind,bytes,updated:Date.now(),expires:Date.now()+days*86400000};memory.set(key,item);while(memory.size>30)memory.delete(memory.keys().next().value);await transact('readwrite',s=>s.put(item));const items=await transact('readonly',s=>s.getAll());if(items){let total=items.reduce((n,x)=>n+x.bytes,0);for(const old of items.sort((a,b)=>a.updated-b.updated)){if(total<=LIMIT&&old.expires>Date.now())continue;await transact('readwrite',s=>s.delete(old.key));memory.delete(old.key);total-=old.bytes;}}return true;}
export async function cacheClear(){memory.clear();await transact('readwrite',s=>s.clear());}
export async function cacheInfo(){const items=await transact('readonly',s=>s.getAll())||[...memory.values()];return {count:items.length,bytes:items.reduce((n,x)=>n+x.bytes,0),durable:!!(await database())};}
